    private const string ActualArguments = """
{"action":"inspect_sources","documentId":"474bf0dd-a235-4deb-9279-b77b99359128","stateId":"aea3acba-dcb7-47dd-82e2-15a88c032780","path":"474bf0dd-a235-4deb-9279-b77b99359128/4f8691db-4c84-47d8-ad77-7c59e9cabc0b","bodyId":"8aee8982-8572-43c8-a87a-75d33ca89cf3","revision":"192d1776-229b-4fe6-85dd-a635d5af5677","limit":50}
""";

    [Theory]
    [InlineData(6000)]
    [InlineData(2400)]
    public void CapturedNativeReceiptKeepsQueryPagingAndShowsContextNavigationBeforeRows(int budget)
    {
        var call = new AiToolCall("captured-native-read", "cad_drawing", ActualArguments);
        Assert.True(AgentToolResultCompactor.TryCompactNativeSelectionPage(ActualReceipt, budget, out var compacted, call));
        Assert.InRange(compacted.Length, 1, budget);
        using var page = JsonDocument.Parse(compacted);
        using var original = JsonDocument.Parse(ActualReceipt);
        var root = page.RootElement;var navigation = root.GetProperty("contextPage");
        Assert.False(root.GetProperty("hasMore").GetBoolean());
        Assert.True(navigation.GetProperty("hasMore").GetBoolean());
        Assert.False(navigation.GetProperty("queryHasMore").GetBoolean());
        int count = root.GetProperty("items").GetArrayLength();Assert.InRange(count, 1, 44);
        Assert.Equal(count, navigation.GetProperty("nextRequest").GetProperty("offset").GetInt32());
        Assert.True(compacted.IndexOf("\"contextPage\"", StringComparison.Ordinal) < compacted.IndexOf("\"items\"", StringComparison.Ordinal));
        for(int i = 0; i < count; i++)
            Assert.Equal(original.RootElement.GetProperty("items")[i].GetRawText(), root.GetProperty("items")[i].GetRawText());
        using var query = JsonDocument.Parse(ActualArguments);
        var next = navigation.GetProperty("nextRequest");
        foreach(string key in new[] { "documentId", "stateId", "path", "bodyId", "revision" })
            Assert.Equal(query.RootElement.GetProperty(key).GetRawText(), next.GetProperty(key).GetRawText());
        Assert.Equal(ActualArguments, call.ArgumentsJson);
    }

    [Fact]
    public void CompleteCapturedReceiptStaysByteIdenticalAndHasNoInventedContextNavigation()
    {
        var call = new AiToolCall("captured-native-read", "cad_drawing", ActualArguments);
        Assert.False(AgentToolResultCompactor.TryCompactNativeSelectionPage(ActualReceipt, ActualReceipt.Length, out var output, call));
        Assert.Equal(ActualReceipt, output);
        using var parsed = JsonDocument.Parse(output);
        Assert.Equal(45, parsed.RootElement.GetProperty("items").GetArrayLength());
        Assert.False(parsed.RootElement.TryGetProperty("contextPage", out _));
        Assert.Equal("CylinderFace", parsed.RootElement.GetProperty("items")[38].GetProperty("geometry").GetString());
    }
